// 仅由独占性能API子进程通过--import载入；记录耗时/数量/固定错误码，不输出SQL参数或凭据。
import {createRequire} from 'node:module';
import {performance,monitorEventLoopDelay} from 'node:perf_hooks';
const require=createRequire(new URL('../../package.json',import.meta.url)),{Pool,Client}=require('pg');
let enabled=false,pool=[],queries=new Map(),errors={},maxWaiting=0,maxCapacity=0,cpuStart,utilizationStart,resourceStart=0,rssPeakBytes=0,memorySamples=0;
const eventLoopDelay=monitorEventLoopDelay({resolution:20});
const memoryTimer=setInterval(()=>{if(enabled){rssPeakBytes=Math.max(rssPeakBytes,process.memoryUsage().rss);memorySamples++;}},500);memoryTimer.unref();
const code=e=>typeof e?.code==='string'&&/^[A-Z0-9_]{1,40}$/.test(e.code)?e.code:'UNCLASSIFIED';
const classify=sql=>/generate_series/.test(sql)?'TRENDS':/visible_history/.test(sql)?'HISTORY':/auth_session/.test(sql)?'AUTH':/inventory_balance/.test(sql)?'LOW_STOCK':/audit_log/.test(sql)?'AUDIT':/SUM\(p.amount_cents/i.test(sql)?'CONSUMPTION':/order_item/.test(sql)?'PRODUCT_QUANTITY':/^\s*(BEGIN|COMMIT|ROLLBACK|SET)/i.test(sql)?'TRANSACTION':'OTHER';
function measure(original,receiver,args,finish){const start=performance.now(),callback=args.at(-1);if(typeof callback==='function'){args[args.length-1]=function(...result){finish(performance.now()-start,result[0]);return Reflect.apply(callback,this,result);};return Reflect.apply(original,receiver,args);}const result=Reflect.apply(original,receiver,args);if(result&&typeof result.then==='function')return result.then(value=>{finish(performance.now()-start);return value;},error=>{finish(performance.now()-start,error);throw error;});return result;}
const connect=Pool.prototype.connect;
Pool.prototype.connect=function(...args){if(!enabled)return Reflect.apply(connect,this,args);maxWaiting=Math.max(maxWaiting,this.waitingCount);maxCapacity=Math.max(maxCapacity,this.options.max??0);return measure(connect,this,args,(ms,e)=>{pool.push(ms);if(e)errors['POOL:'+code(e)]=(errors['POOL:'+code(e)]??0)+1;});};
const query=Client.prototype.query;
Client.prototype.query=function(...args){if(!enabled)return Reflect.apply(query,this,args);const text=typeof args[0]==='string'?args[0]:args[0]?.text??'',kind=classify(text);return measure(query,this,args,(ms,e)=>{const values=queries.get(kind)??[];values.push(ms);queries.set(kind,values);if(e)errors['QUERY:'+code(e)]=(errors['QUERY:'+code(e)]??0)+1;});};
const stats=values=>{const rows=[...values].sort((a,b)=>a-b),p=x=>rows.length?Math.round(rows[Math.ceil(rows.length*x)-1]*100)/100:0;return {count:rows.length,p50Ms:p(.5),p95Ms:p(.95),p99Ms:p(.99),maxMs:p(1)};};
process.on('message',message=>{if(message?.type==='performance-process-shutdown')process.exit(0);});
process.on('message',message=>{if(message?.type==='performance-probe-start'){pool=[];queries=new Map();errors={};maxWaiting=0;maxCapacity=0;cpuStart=process.cpuUsage();utilizationStart=performance.eventLoopUtilization();resourceStart=performance.now();rssPeakBytes=process.memoryUsage().rss;memorySamples=1;eventLoopDelay.reset();eventLoopDelay.enable();enabled=true;process.send?.({type:'performance-probe-started'});}if(message?.type==='performance-probe-stop'){enabled=false;eventLoopDelay.disable();const elapsedMs=performance.now()-resourceStart,cpu=process.cpuUsage(cpuStart),eventLoop=performance.eventLoopUtilization(utilizationStart),memory=process.memoryUsage();rssPeakBytes=Math.max(rssPeakBytes,memory.rss);process.send?.({type:'performance-probe-stopped',poolAcquire:stats(pool),queries:Object.fromEntries([...queries].map(([key,values])=>[key,stats(values)])),errors,maxWaiting,maxCapacity,apiResources:{elapsedMs,cpuMicroseconds:cpu,cpuOneCorePercent:(cpu.user+cpu.system)/elapsedMs/10,eventLoopUtilization:eventLoop,eventLoopDelayMs:{p50:eventLoopDelay.percentile(50)/1e6,p95:eventLoopDelay.percentile(95)/1e6,p99:eventLoopDelay.percentile(99)/1e6,max:eventLoopDelay.max/1e6},rssPeakBytes,rssEndBytes:memory.rss,heapUsedEndBytes:memory.heapUsed,memorySamples,samplingIntervalMs:500}});}});
